"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8264],{28653:e=>{e.exports=JSON.parse('{"functions":[{"name":"InitServer","desc":"Compiles the `SOUNDS` Configuration into the schema, publishes it to clients, and destroys the Configuration.\\n\\n:::danger\\nCall this once. The schema is locked after it is built, so sounds and SoundGroups cannot be added while the game\\nruns.\\n:::\\n\\n```lua\\nlocal ReplicatedStorage = game:GetService(\\"ReplicatedStorage\\")\\nlocal ServerStorage = game:GetService(\\"ServerStorage\\")\\n\\nlocal VluxySF = require(ReplicatedStorage.Packages.VluxySF)\\n\\nVluxySF.Startup.InitServer(ServerStorage.SOUNDS)\\n```","params":[{"name":"soundFolder","desc":"The `SOUNDS` Configuration.","lua_type":"Configuration"}],"returns":[],"function_type":"static","realm":["Server"],"source":{"line":94,"path":"lib/Api/Startup.luau"}},{"name":"InitClient","desc":"Receives the schema from the server, then builds and preloads every sound tagged for preloading.\\n\\nThe schema is ready as soon as it is received, so `WaitForSchema` and `ConnectForSchema` in other scripts resume\\nthen. This call itself yields until the preloads finish or `timeout` seconds pass, whichever comes first, and\\nwarns if it timed out. Pass `0` to not wait at all: the preloads still run in the background, no warning is\\nprinted, and you can check on them with `IsPreloaded` or `WaitForPreload`.\\n\\n:::danger\\nCall this once per client.\\n:::\\n\\n```lua\\nlocal ReplicatedStorage = game:GetService(\\"ReplicatedStorage\\")\\n\\nlocal VluxySF = require(ReplicatedStorage.Packages.VluxySF)\\n\\nVluxySF.Startup.InitClient(4)\\n```","params":[{"name":"timeout","desc":"How long to wait for the preloads, in seconds. Default is 5. `0` does not wait.","lua_type":"number?"}],"returns":[],"function_type":"static","realm":["Client"],"yields":true,"source":{"line":157,"path":"lib/Api/Startup.luau"}},{"name":"IsInitialized","desc":"```lua\\nprint(VluxySF.Startup.IsInitialized())\\n```","params":[],"returns":[{"desc":"Whether the schema is ready on this side.","lua_type":"boolean"}],"function_type":"static","source":{"line":217,"path":"lib/Api/Startup.luau"}},{"name":"WaitForSchema","desc":"Yields until the schema is ready. Returns right away if it already is.\\n\\n```lua\\nVluxySF.Startup.WaitForSchema()\\n\\nVluxySF.FetchPlayOnce(\\"MySound\\")\\n```","params":[],"returns":[],"function_type":"static","yields":true,"source":{"line":234,"path":"lib/Api/Startup.luau"}},{"name":"ConnectForSchema","desc":"Runs the callback once the schema is ready, without yielding. If it already is, the callback runs in a new thread\\nright away.\\n\\n```lua\\nVluxySF.Startup.ConnectForSchema(function()\\n\\tVluxySF.FetchPlayOnce(\\"MySound\\")\\nend)\\n\\n-- This line does not wait.\\n```","params":[{"name":"finished","desc":"Runs when the schema is ready.","lua_type":"() -> ()"}],"returns":[{"desc":"Cancels the callback if it has not run yet.","lua_type":"() -> ()"}],"function_type":"static","source":{"line":260,"path":"lib/Api/Startup.luau"}},{"name":"IsPreloaded","desc":"```lua\\nprint(VluxySF.Startup.IsPreloaded())\\n```","params":[],"returns":[{"desc":"Whether the sounds tagged for preloading have finished loading.","lua_type":"boolean"}],"function_type":"static","realm":["Client"],"source":{"line":285,"path":"lib/Api/Startup.luau"}},{"name":"WaitForPreload","desc":"Yields until the sounds tagged for preloading have finished loading. Returns right away if they have.\\nUseful after `InitClient(0)`.\\n\\n```lua\\nVluxySF.Startup.InitClient(0)\\n\\n-- Do other startup work here.\\n\\nVluxySF.Startup.WaitForPreload()\\n```","params":[],"returns":[],"function_type":"static","realm":["Client"],"yields":true,"source":{"line":307,"path":"lib/Api/Startup.luau"}}],"properties":[],"types":[],"name":"Startup","desc":"Starts the library and tells you when it is ready.\\n\\nThe server compiles the `SOUNDS` Configuration into the schema once. Every client receives that schema when it\\njoins. Until a side has started, most of the library errors when used, so other scripts should wait with\\n`WaitForSchema` or `ConnectForSchema`.","source":{"line":26,"path":"lib/Api/Startup.luau"}}')}}]);